INSERT INTO fee_types (id, fee_name, fee_code, default_price, unit) VALUES (1, 'Phí Quản lý', 'PQL', 7000, 'm²'), (2, 'Phí Gửi xe', 'PGX', 0, 'Tháng'), (3, 'Phí Điện', 'PD', 3000, 'kWh'), (4, 'Phí Nước', 'PN', 15000, 'm³');
